<?php
namespace VPM\Booking;
if(!defined('ABSPATH'))exit;
/** Opt-in WordPress transport, restricted to a single operator-owned test mailbox. */
final class MailTransport {
    public static function save(array $d):void {Config::require(current_user_can('manage_options'),'permission_denied');$to=trim((string)($d['test_mail_to']??''));Config::require($to===''||is_email($to),'invalid_test_mail_address');if(!empty($d['test_mail_enabled'])){Config::require(is_email($to)&&is_email(Branding::get()['sender_email']),'mail_sender_required');Config::require(!Automation::configured(),'mail_transport_conflict');}update_option('vpm_booking_test_mail_to',$to,false);update_option('vpm_booking_test_mail_enabled',!empty($d['test_mail_enabled']),false);}
    public static function render(array $payload,string $topic):array {
        $brand=$payload['branding']??Branding::mail_data();$partner=str_starts_with($topic,'partner.');$titles=array('booking.requested'=>'Ihre Buchungsanfrage ist eingegangen','booking.confirmed'=>'Ihre Buchung ist bestätigt','booking.cancelled'=>'Ihre Buchung wurde storniert','booking.partner_message_approved'=>'Neue Nachricht zu Ihrer Buchung','booking.inquiry_received'=>'Ihr Anliegen ist eingegangen','partner.support_reminder'=>'Erinnerung: Kundenanfrage beantworten','partner.support_escalated'=>'Überfällig: Kundenanfrage beantworten','partner.cancellation_reminder'=>'Erinnerung: Stornowunsch bearbeiten','partner.customer_inquiry'=>'Neue Kundenanfrage','partner.cancellation_requested'=>'Neuer Stornowunsch','partner.booking_requested'=>'Neue Buchungsanfrage','refund.succeeded'=>'Erstattung zu Ihrer Buchung','partner.invoice_required'=>'Rechnung für die Buchung erstellen','partner.credit_note_required'=>'Gutschrift zur Buchung prüfen');$title=$titles[$topic]??'Information zu einer Buchung';$number=(string)($payload['booking_number']??'');$html='<h1>'.esc_html($title).'</h1><p><strong>'.esc_html($number).'</strong></p>';
        if(!empty($payload['message']))$html.='<div style="padding:16px;background:#f3f6fa;border-radius:8px">'.nl2br(esc_html($payload['message'])).'</div>';
        $html.='<p>Flughafen: '.esc_html($payload['airport']??'').'</p>';$travel=$payload['travel']??array();if(!empty($travel['timezone'])){$zone=new \DateTimeZone($travel['timezone']);foreach(array('flight_departure_utc'=>'Geplanter Abflug','flight_return_utc'=>'Geplante Rücklandung','departure_utc'=>'Kalkulierter Parkbeginn','return_utc'=>'Kalkuliertes Parkende')as $key=>$label)if(!empty($travel[$key]))$html.='<p>'.esc_html($label).': '.esc_html(wp_date('d.m.Y H:i',$travel[$key],$zone)).'</p>';}
        $customer=$payload['customer']??array();foreach(array('first_name'=>'Vorname','last_name'=>'Nachname','phone'=>'Telefon','plate'=>'Kennzeichen','make'=>'Fahrzeug','company'=>'Firma','street'=>'Straße','postcode'=>'PLZ','city'=>'Ort','country'=>'Land')as $key=>$label)if(!empty($customer[$key]))$html.='<p>'.esc_html($label).': '.esc_html($customer[$key]).'</p>';
        $selection=$payload['offer_selection']??array();if(!empty($selection['service']))$html.='<p>Service: '.esc_html($selection['service']).'</p>';if(!empty($customer['height_cm']))$html.='<p>Fahrzeughöhe: '.esc_html(number_format((int)$customer['height_cm']/100,2,',','')).' m</p>';if(!empty($customer['passengers']))$html.='<p>Personen: '.(int)$customer['passengers'].'</p>';if(!empty($selection['product_name']))$html.='<p>'.esc_html($selection['product_name']).'</p>';foreach($selection['addons']??array()as $extra)$html.='<p>'.(int)$extra['quantity'].' × '.esc_html($extra['label']).' · '.Experience::money((int)$extra['amount_cents']).'</p>';
        $amounts=$payload['amounts']??array();foreach(array('base'=>'Gesamt vor Rabatt','discount'=>'Rabatt','charged'=>'Gesamtbetrag')as $key=>$label)if(isset($amounts[$key]))$html.='<p>'.esc_html($label).': <strong>'.Experience::money((int)$amounts[$key]).'</strong></p>';
        if(!$partner){$service=$payload['partner_service']??array();if(!empty($service['confirmed_handover_utc'])&&!empty($travel['timezone']))$html.='<p>Übergabezeit: '.esc_html(wp_date('d.m.Y H:i',$service['confirmed_handover_utc'],new \DateTimeZone($travel['timezone']))).'</p>';if(!empty($service['support_phone']))$html.='<p>Telefon des Anbieters: '.esc_html($service['support_phone']).'</p>';foreach($service['points']??array()as $point){$html.='<p><strong>'.esc_html($point['name_de']??'').'</strong><br>'.esc_html($point['address']??'').'<br>'.nl2br(esc_html($point['instructions_de']??'')).'</p>';if(!empty($point['directions_url']))$html.='<p><a href="'.esc_url($point['directions_url']).'">Route öffnen</a></p>';}$url=$payload['support_url']??Journey::support_url($number);$label='Anliegen zu meiner Buchung';$html.='<p>Bitte nutzen Sie bei Fragen oder Stornowünschen das Formular und halten Sie Ihre Buchungsnummer bereit.</p>';}
        else{$url=$payload['portal_url']??add_query_arg('vpm_partner_login',1,home_url('/'));$label='Im Partnerportal bearbeiten';}
        $html.='<p><a style="display:inline-block;padding:12px 20px;border-radius:6px;background:'.esc_attr($brand['primary']).';color:'.esc_attr($brand['primary_text']).'" href="'.esc_url($url).'">'.esc_html($label).'</a></p>';
        $body='<html><body style="margin:0;background:'.esc_attr($brand['background']).';font-family:Arial,sans-serif;color:'.esc_attr($brand['text']).'"><div style="max-width:640px;margin:auto;padding:28px;background:'.esc_attr($brand['surface']).'">'.(!empty($brand['logo_url'])?'<img src="'.esc_url($brand['logo_url']).'" alt="'.esc_attr($brand['name']).'" style="max-width:180px;max-height:64px">':'<strong>'.esc_html($brand['name']).'</strong>').$html.'</div></body></html>';
        return array('subject'=>$title.($number?' · '.$number:''),'body'=>$body);
    }
    public static function run():void {
        if(!get_option('vpm_booking_test_mail_enabled',false)||Automation::configured())return;$to=get_option('vpm_booking_test_mail_to','');$brand=Branding::get();if(!is_email($to)||!is_email($brand['sender_email']))return;global $wpdb;
        $ids=$wpdb->get_col($wpdb->prepare('SELECT id FROM '.DB::table('outbox')." WHERE purpose='transactional' AND (status='pending' OR (status='processing' AND locked_until<%d)) AND next_attempt<=%d AND (topic LIKE 'booking.%%' OR topic LIKE 'partner.%%' OR topic LIKE 'refund.%%' OR topic LIKE 'platform.%%') ORDER BY id LIMIT 10",time(),time()));
        foreach($ids as $id){$lease=bin2hex(random_bytes(16));$claimed=DB::query($wpdb->prepare('UPDATE '.DB::table('outbox')." SET status='processing',locked_until=%d,locked_by=%s WHERE id=%d AND (status='pending' OR (status='processing' AND locked_until<%d))",time()+120,$lease,$id,time()));if(!$claimed)continue;$row=DB::row('outbox','id',(int)$id);try{$payload=Config::open($row['payload']);$mail=self::render($payload,$row['topic']);$headers=array('Content-Type: text/html; charset=UTF-8','From: '.$brand['sender_name'].' <'.$brand['sender_email'].'>');if(is_email($brand['reply_email']))$headers[]='Reply-To: '.$brand['reply_email'];$messageID='<vpm-'.hash('sha256',$row['event_key']).'@'.substr(strrchr($brand['sender_email'],'@'),1).'>';$setID=function($phpmailer)use($messageID){$phpmailer->MessageID=$messageID;$phpmailer->Timeout=20;};add_action('phpmailer_init',$setID);try{$sent=wp_mail($to,'[TEST] '.$mail['subject'],$mail['body'],$headers);}finally{remove_action('phpmailer_init',$setID);}Config::require($sent,'mail_not_accepted');DB::update('outbox',array('status'=>'dispatched','locked_until'=>0,'error_code'=>''),array('id'=>$id,'locked_by'=>$lease));}
            catch(\Throwable $e){$attempts=(int)$row['attempts']+1;DB::update('outbox',array('status'=>$attempts>=8?'attention':'pending','locked_until'=>0,'attempts'=>$attempts,'next_attempt'=>time()+min(3600,30*2**min($attempts,6)),'error_code'=>'test_mail_retry_required'),array('id'=>$id,'locked_by'=>$lease));}
        }
    }
    public static function admin():void {echo '<h3>Stripe-Gastzahlung im Testmodus</h3><form method="post">';wp_nonce_field('vpm_booking_operations');echo '<input type="hidden" name="vpm_operation" value="guest_payment"><label><input type="checkbox" name="enabled" value="1" '.checked(get_option('vpm_booking_guest_payment_enabled',false),true,false).'> Sicheren Stripe-Testcheckout für Gäste aktivieren</label><p>Nur mit privatem Stripe-Testschlüssel, Webhook und Test-Zahlungszuordnung der Partner. Keine Live-Zahlungen. Die Rückkehrseite bestätigt keinen Zahlungserfolg.</p><button class="button">Testkasse speichern</button></form>';echo '<h3>Geschützter Testversand</h3><p>Optionaler Versand über WordPress/wp_mail. Alle Nachrichten gehen ausschließlich an die hier hinterlegte eigene Testadresse. Keine Zustellung an echte Kunden oder Partner. Ein SMTP-Plugin kann wp_mail transportieren; Zugangsdaten dort sicher konfigurieren. „Übergeben“ bedeutet nicht nachweislich zugestellt.</p><form method="post">';wp_nonce_field('vpm_booking_operations');echo '<input type="hidden" name="vpm_operation" value="test_mail"><label>Eigenes Testpostfach <input type="email" name="test_mail_to" value="'.esc_attr(get_option('vpm_booking_test_mail_to','')).'"></label><label><input type="checkbox" name="test_mail_enabled" value="1" '.checked(get_option('vpm_booking_test_mail_enabled',false),true,false).'> Testversand aktivieren (Absender zuvor unter Branding konfigurieren)</label><button class="button">Testversand speichern</button></form>';}
}
